"""Порт формы спана: ЧЕТЫРЕ операции, которых хватает всем сегодняшним сайтам.

**Почему `Protocol`, а не `ABC`.** В `core` нет ни одного `abstractmethod`, а рабочий образец стиля в
этом проекте — `Retriever(Protocol)` (`retrieval/pgvector.py`). Порт даёт форме спана ИМЯ; второй вендор
обязан прийти через тот же вход обращения (правило «у механизма, нужного двум потребителям, один вход»),
и это же держит гейт `make arch`.

**Почему операций именно четыре.** Их ровно столько, сколько нужно вызывающим, и ни одной «на будущее»:
рендер атрибутов, запись расхода, адрес приёма и атрибуты РЕСУРСА. Всё прочее (открытие спана, пометка
ошибки, батчинг, создание провайдера) остаётся в `core` и ОБЩЕ обоим вендорам — это OTEL-API, а не
знание о вендоре.

**Почему ресурс — дело вендора.** Ресурс несёт `service.name`: у Agenta он декоративный (приём его
игнорирует, привязка идёт атрибутами спана), а у OpenLIT — ключ группировки (и, как выяснилось, ещё и
условие появления службы в разделе «Agents», см. `vendors/openlit.py`). Значит состав ресурса —
ровно такая же вендорская форма, как и форма спана, и жить она должна здесь, а не в `telemetry.py`.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Protocol

from agent_core.vendors.neutral import SpanShape, Usage


@dataclass(frozen=True)
class Receiver:
    """Куда вендор принимает спаны: адрес и заголовки авторизации."""

    endpoint: str = ""
    headers: dict[str, str] = field(default_factory=dict)


class TraceShape(Protocol):
    """Форма спана у одного вендора: как он её пишет и куда принимает.

    **Почему адрес — часть порта, а не константа в `telemetry.py`.** У вендоров РАЗНЫЕ приём и
    авторизация (Agenta — `POST /otlp/v1/traces` с `Authorization: ApiKey …`; OpenLIT — свой приём
    OTLP). Оставь адрес литералом — при `PLATFORM_VENDOR=openlit` спаны МОЛЧА продолжали бы уезжать в
    Agenta: механизм заявлял бы переключение, которого не делает, а молчание читается как
    подтверждение.
    """

    def attributes(self, shape: SpanShape) -> dict:
        """Атрибуты спана формы `shape` — как их понимает ЭТОТ вендор."""
        ...

    def set_usage(self, current, usage: Usage) -> None:
        """Записать расход на УЖЕ открытый спан (`current` может быть `None` — трейсера нет)."""
        ...

    def receiver(self, settings) -> Receiver:
        """Адрес и заголовки приёма ЭТОГО вендора. Пустой адрес — «трассировки нет» (штатно)."""
        ...

    def resource_attributes(self, settings, service_name: str) -> dict:
        """Атрибуты РЕСУРСА для службы `service_name` в форме ЭТОГО вендора.

        Вход один: имя службы. Всё остальное (маркеры, окружение) вендор решает сам — иначе вызывающий
        код начал бы знать, что одному приёмнику для группировки нужен маркер, а другому нет.
        """
        ...
